// Accessibility tests: WCAG 2.2 Level AA (axe-core, plus targeted checks for
// the 2.2-specific criteria) and the WAI-ARIA Authoring Practices Guide (APG)
// keyboard and ARIA behaviour for every widget the product page uses.
import { test, expect } from '@playwright/test'
import {
  openProductPage,
  expectNoAxeViolations,
  chooseFirstAvailableSize,
  photoCarousel,
  visiblePhotoKey,
  nextPhotoButton,
  priceInfoButton,
  colorRadioGroup,
  colorRadios,
  changeColorButton,
  sizeCombobox,
  sizeListbox,
  openSizeList,
  sizeGuideTrigger,
  sizeGuideDialog,
  quantityInput,
  addToCartButton,
  wishlistButton,
  infoTablist,
  infoTab,
  questionButtons,
  pageFooter,
  cartControl,
} from './helpers.js'

// True when the element shows a visible focus indicator (WCAG 2.4.7).
async function hasFocusIndicator(locator) {
  return locator.evaluate((el) => {
    const s = getComputedStyle(el)
    const outline = s.outlineStyle !== 'none' && parseFloat(s.outlineWidth) > 0
    const shadow = s.boxShadow !== 'none'
    return outline || shadow
  })
}

// True when the centre of the focused element is not covered by other content (WCAG 2.4.11).
async function isNotObscured(locator) {
  return locator.evaluate((el) => {
    const r = el.getBoundingClientRect()
    const hit = document.elementFromPoint(
      r.left + r.width / 2,
      r.top + r.height / 2,
    )
    return !!hit && (hit === el || el.contains(hit))
  })
}

test.describe('WCAG 2.2 AA: whole page', () => {
  test('default page has no axe violations for WCAG 2.2 A and AA', async ({
    page,
  }) => {
    await openProductPage(page)
    await expectNoAxeViolations(page, 'default state')
  })

  test('page has a language, a title, one h1 and the expected landmarks', async ({
    page,
  }) => {
    await openProductPage(page)
    await expect(page.locator('html')).toHaveAttribute('lang', /.+/)
    await expect(page).toHaveTitle(/Trail Runner 2/)
    await expect(page.getByRole('heading', { level: 1 })).toHaveCount(1)
    await expect(page.getByRole('banner')).toHaveCount(1)
    await expect(page.getByRole('main')).toHaveCount(1)
    await expect(page.getByRole('contentinfo')).toHaveCount(1)
    await expect(page.getByRole('navigation').first()).toBeVisible()
  })

  test('content reflows at 320 CSS pixels wide without horizontal scrolling (WCAG 1.4.10)', async ({
    page,
  }) => {
    await page.setViewportSize({ width: 320, height: 800 })
    await openProductPage(page)
    const overflow = await page.evaluate(
      () =>
        document.documentElement.scrollWidth -
        document.documentElement.clientWidth,
    )
    expect(overflow).toBeLessThanOrEqual(0)
  })

  test('every interactive control shows a visible focus indicator (WCAG 2.4.7)', async ({
    page,
  }) => {
    await openProductPage(page)
    const controls = {
      cart: cartControl(page),
      'next photo': nextPhotoButton(photoCarousel(page)),
      'price info': priceInfoButton(page),
      'change colour': changeColorButton(page),
      size: sizeCombobox(page),
      'size guide': sizeGuideTrigger(page),
      quantity: quantityInput(page),
      'add to cart': addToCartButton(page),
      wishlist: wishlistButton(page),
      'details tab': infoTab(page, 'Details'),
      'first question': questionButtons(page).first(),
    }
    for (const [name, locator] of Object.entries(controls)) {
      await locator.focus()
      expect(await hasFocusIndicator(locator), name).toBe(true)
    }
  })

  test('focused controls are not hidden behind other content (WCAG 2.4.11)', async ({
    page,
  }) => {
    await openProductPage(page)
    for (const locator of [
      addToCartButton(page),
      wishlistButton(page),
      quantityInput(page),
      sizeCombobox(page),
      infoTab(page, 'Details'),
    ]) {
      await locator.focus()
      expect(await isNotObscured(locator)).toBe(true)
    }
  })

  test('footer links all have descriptive names (WCAG 2.4.4)', async ({
    page,
  }) => {
    await openProductPage(page)
    const links = pageFooter(page).getByRole('link')
    const count = await links.count()
    expect(count).toBeGreaterThan(0)
    for (let i = 0; i < count; i++) {
      await expect(links.nth(i)).toHaveAccessibleName(/\S/)
      await expect(links.nth(i)).not.toHaveAccessibleName(/^(click here|here|more|read more)$/i)
    }
  })
})

test.describe('WCAG 2.2 AA: after interacting', () => {
  test('no axe violations with the price tooltip shown', async ({ page }) => {
    await openProductPage(page)
    await priceInfoButton(page).focus()
    await expect(page.getByRole('tooltip')).toBeVisible()
    await expectNoAxeViolations(page, 'price tooltip shown')
  })

  test('no axe violations with the size list open', async ({ page }) => {
    await openProductPage(page)
    await openSizeList(page)
    await expectNoAxeViolations(page, 'size list open')
  })

  test('no axe violations with the size guide open', async ({ page }) => {
    await openProductPage(page)
    await sizeGuideTrigger(page).click()
    await expect(sizeGuideDialog(page)).toBeVisible()
    await expectNoAxeViolations(page, 'size guide open')
  })

  test('no axe violations with each information tab selected', async ({
    page,
  }) => {
    await openProductPage(page)
    for (const name of ['Reviews', 'Shipping', 'Details']) {
      await infoTab(page, name).click()
      await expectNoAxeViolations(page, `${name} tab selected`)
    }
  })

  test('no axe violations with a question answer open', async ({ page }) => {
    await openProductPage(page)
    await questionButtons(page).first().click()
    await expectNoAxeViolations(page, 'question open')
  })

  test('no axe violations after an add-to-cart error', async ({ page }) => {
    await openProductPage(page)
    await addToCartButton(page).click()
    await expect(page.getByRole('alert')).toBeVisible()
    await expectNoAxeViolations(page, 'missing size error')
  })
})

test.describe('WCAG 2.2 AA: specific criteria', () => {
  test('an error names the missing size and is linked to the size control (WCAG 3.3.1)', async ({
    page,
  }) => {
    await openProductPage(page)
    await addToCartButton(page).click()

    await expect(
      page.getByRole('alert').filter({ hasText: /size/i }),
    ).toBeVisible()
    await expect(sizeCombobox(page)).toHaveAttribute('aria-invalid', 'true')
  })

  test('the added-to-cart confirmation is announced in a status region and focus stays on the button (WCAG 4.1.3)', async ({
    page,
  }) => {
    await openProductPage(page)
    await chooseFirstAvailableSize(page)
    await addToCartButton(page).focus()
    await page.keyboard.press('Enter')

    await expect(
      page
        .getByRole('status')
        .or(page.getByRole('alert'))
        .filter({ hasText: /added to (your )?cart/i }),
    ).toBeVisible()
    await expect(addToCartButton(page)).toBeFocused()
  })
})

test.describe('APG: breadcrumb', () => {
  test('is a labelled navigation list with the current page marked by aria-current', async ({
    page,
  }) => {
    await openProductPage(page)
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await expect(path.locator('[aria-current="page"]')).toHaveText(
      'Trail Runner 2',
    )
    await expect(path.getByRole('list')).toHaveCount(1)
  })
})

test.describe('APG: carousel', () => {
  test('is a labelled carousel with numbered slides, and its buttons work from the keyboard', async ({
    page,
  }) => {
    await openProductPage(page)
    const carousel = photoCarousel(page)
    await expect(carousel).toHaveAttribute('aria-roledescription', 'carousel')

    const slides = carousel.locator('[aria-roledescription="slide"]')
    const total = await slides.count()
    expect(total).toBeGreaterThan(1)
    for (let i = 0; i < total; i++) {
      await expect(slides.nth(i)).toHaveAttribute(
        'aria-label',
        new RegExp(`${i + 1} of ${total}`),
      )
    }

    const first = await visiblePhotoKey(carousel)
    await nextPhotoButton(carousel).focus()
    await page.keyboard.press('Enter')
    await expect.poll(() => visiblePhotoKey(carousel)).not.toBe(first)
  })
})

test.describe('APG: select-only combobox (size)', () => {
  test('exposes its popup and state, and can be operated from the keyboard', async ({
    page,
  }) => {
    await openProductPage(page)
    const combo = sizeCombobox(page)
    await expect(combo).toHaveAttribute('aria-haspopup', 'listbox')
    await expect(combo).toHaveAttribute('aria-expanded', 'false')

    await combo.focus()
    await page.keyboard.press('Enter')
    await expect(combo).toHaveAttribute('aria-expanded', 'true')

    const listbox = sizeListbox(page)
    await expect(listbox).toBeVisible()
    const listboxId = await listbox.getAttribute('id')
    expect(listboxId, 'listbox has an id').toBeTruthy()
    await expect(combo).toHaveAttribute('aria-controls', listboxId)

    // Move the active option until it lands on one that can be picked.
    let activeId = null
    for (let i = 0; i < 20; i++) {
      await page.keyboard.press('ArrowDown')
      activeId = await combo.getAttribute('aria-activedescendant')
      expect(activeId, 'an option is announced as active').toBeTruthy()
      const active = page.locator(`[id="${activeId}"]`)
      await expect(active).toHaveAttribute('role', 'option')
      if ((await active.getAttribute('aria-disabled')) !== 'true') break
    }
    const expected = (
      await page.locator(`[id="${activeId}"]`).innerText()
    ).trim()

    await page.keyboard.press('Enter')
    await expect(listbox).toBeHidden()
    await expect(combo).toHaveAttribute('aria-expanded', 'false')
    await expect(combo).toBeFocused()
    await expect(combo).toContainText(expected)
  })

  test('Escape closes the list without changing the size', async ({ page }) => {
    await openProductPage(page)
    const combo = sizeCombobox(page)
    const before = await combo.innerText()

    await combo.focus()
    await page.keyboard.press('Enter')

