})

test.describe('APG: radio group (colour)', () => {
  test('is a labelled radio group, and arrow keys move and check the colour', async ({
    page,
  }) => {
    await openProductPage(page)
    await changeColorButton(page).click()
    await expect(colorRadioGroup(page)).toBeVisible()
    await expect(colorRadios(page).filter({ visible: true })).toHaveCount(3)

    const blue = page.getByRole('radio', { name: 'Blue' })
    await blue.focus()
    await page.keyboard.press('ArrowRight')
    await expect(page.getByRole('radio', { name: 'Black' })).toBeChecked()
    await expect(page.getByRole('radio', { name: 'Black' })).toBeFocused()

    await page.keyboard.press('ArrowRight')
    await expect(page.getByRole('radio', { name: 'Grey' })).toBeChecked()

    await page.keyboard.press('ArrowRight')
    await expect(page.getByRole('radio', { name: 'Blue' })).toBeChecked()
  })

  test('the change control is a disclosure button that reports its state', async ({
    page,
  }) => {
    await openProductPage(page)
    const change = changeColorButton(page)
    await expect(change).toHaveAttribute('aria-expanded', 'false')
    await change.click()
    await expect(change).toHaveAttribute('aria-expanded', 'true')
    const controls = await change.getAttribute('aria-controls')
    expect(controls, 'disclosure names the content it controls').toBeTruthy()
    await expect(page.locator(`[id="${controls}"]`)).toBeVisible()
  })
})

test.describe('APG: spin button (quantity)', () => {
  test('ArrowUp and ArrowDown change the quantity by one', async ({ page }) => {
    await openProductPage(page)
    const quantity = quantityInput(page)
    await quantity.fill('1')
    await quantity.focus()
    await page.keyboard.press('ArrowUp')
    await expect(quantity).toHaveValue('2')
    await page.keyboard.press('ArrowDown')
    await expect(quantity).toHaveValue('1')
  })
})

test.describe('APG: toggle button (wishlist)', () => {
  test('exposes aria-pressed and toggles with Space and Enter', async ({
    page,
  }) => {
    await openProductPage(page)
    const heart = wishlistButton(page)
    await expect(heart).toHaveAttribute('aria-pressed', 'false')
    await heart.focus()

    await page.keyboard.press(' ')
    await expect(heart).toHaveAttribute('aria-pressed', 'true')
    await page.keyboard.press('Enter')
    await expect(heart).toHaveAttribute('aria-pressed', 'false')
  })
})

test.describe('APG: tooltip (price information)', () => {
  test('shows on focus, is described by the trigger, and is dismissed with Escape', async ({
    page,
  }) => {
    await openProductPage(page)
    const trigger = priceInfoButton(page)
    await trigger.focus()

    const tooltip = page.getByRole('tooltip')
    await expect(tooltip).toBeVisible()
    await expect(trigger).toHaveAccessibleDescription(/includes?.*tax/i)

    await page.keyboard.press('Escape')
    await expect(tooltip).toBeHidden()
    await expect(trigger).toBeFocused()
  })
})

test.describe('APG: modal dialog (size guide)', () => {
  test('is a labelled modal dialog that takes focus, traps Tab and returns focus on close', async ({
    page,
  }) => {
    await openProductPage(page)
    const trigger = sizeGuideTrigger(page)
    await trigger.click()

    const dialog = sizeGuideDialog(page)
    await expect(dialog).toBeVisible()
    await expect(dialog).toHaveAttribute('aria-modal', 'true')

    const focusInsideDialog = () =>
      page.evaluate(() => !!document.activeElement?.closest('[role="dialog"]'))
    expect(await focusInsideDialog()).toBe(true)

    for (let i = 0; i < 25; i++) {
      await page.keyboard.press('Tab')
      expect(await focusInsideDialog()).toBe(true)
    }

    await page.keyboard.press('Escape')
    await expect(dialog).toBeHidden()
    await expect(trigger).toBeFocused()
  })
})

test.describe('APG: tabs (more information)', () => {
  test('tabs are linked to their panel, and arrow, Home and End keys move between them', async ({
    page,
  }) => {
    await openProductPage(page)
    await expect(infoTablist(page)).toBeVisible()

    const details = infoTab(page, 'Details')
    await expect(details).toHaveAttribute('aria-selected', 'true')
    await details.focus()

    await page.keyboard.press('ArrowRight')
    const reviews = infoTab(page, 'Reviews')
    await expect(reviews).toBeFocused()
    await expect(reviews).toHaveAttribute('aria-selected', 'true')
    await expect(details).toHaveAttribute('aria-selected', 'false')

    const panel = page.getByRole('tabpanel')
    await expect(panel).toBeVisible()
    await expect(panel).toHaveAttribute(
      'aria-labelledby',
      (await reviews.getAttribute('id')) ?? '',
    )
    await expect(reviews).toHaveAttribute(
      'aria-controls',
      (await panel.getAttribute('id')) ?? '',
    )

    await page.keyboard.press('End')
    await expect(infoTab(page, 'Shipping')).toBeFocused()
    await page.keyboard.press('Home')
    await expect(details).toBeFocused()
  })
})

test.describe('APG: accordion (questions)', () => {
  test('each question is a button inside a heading, with aria-expanded and aria-controls', async ({
    page,
  }) => {
    await openProductPage(page)
    const buttons = questionButtons(page)
    const count = await buttons.count()
    expect(count).toBeGreaterThanOrEqual(3)

    for (let i = 0; i < count; i++) {
      const button = buttons.nth(i)
      const inHeading = await button.evaluate(
        (el) => !!el.closest('h1,h2,h3,h4,h5,h6'),
      )
      expect(inHeading, 'question button sits in a heading').toBe(true)
      await expect(button).toHaveAttribute('aria-expanded', 'false')
      expect(await button.getAttribute('aria-controls')).toBeTruthy()
    }
  })

  test('Enter and Space open and close an answer', async ({ page }) => {
    await openProductPage(page)
    const question = questionButtons(page).first()
    await question.focus()

    await page.keyboard.press('Enter')
    await expect(question).toHaveAttribute('aria-expanded', 'true')

    await page.keyboard.press(' ')
    await expect(question).toHaveAttribute('aria-expanded', 'false')
  })
})

