      expect(await readCartCount(page)).toBeGreaterThanOrEqual(0)
    })
  })

  test.describe('Menu', () => {
    test('offers the main store sections at the top of the page', async ({
      page,
    }) => {
      await openProductPage(page)
      const menu = page
        .getByRole('navigation')
        .filter({ has: page.getByRole('link', { name: 'Men' }) })

