      await openProductPage(page)
      const carousel = photoCarousel(page)
      const first = await visiblePhotoKey(carousel)

      await nextPhotoButton(carousel).click()
      await expect
        .poll(() => visiblePhotoKey(carousel))
        .not.toBe(first)
    })

    test('goes back to the first photo after the last one', async ({
      page,
