      await expect(colorRadios(page).filter({ visible: true })).toHaveCount(1)
      await expect(
        page.getByRole('radio', { name: /^(blue|black|grey)$/i, checked: true }),
      ).toHaveCount(1)

      const swatch = colorRadios(page).filter({ visible: true }).first()
      const { width, height, radius } = await swatch.evaluate((el) => {
        const r = el.getBoundingClientRect()
        return {
          width: r.width,
