import { useState } from 'react'

export default function PhotoCarousel({ photos, productName }) {
  const [index, setIndex] = useState(0)
  const total = photos.length
  const next = () => setIndex((i) => (i + 1) % total)
  const prev = () => setIndex((i) => (i - 1 + total) % total)

  return (
    <section
      className="carousel"
      role="group"
      aria-roledescription="carousel"
      aria-label={`${productName} photos`}
    >
      <div className="carousel__slides">
        {photos.map((photo, i) => (
          <div
            key={photo.src}
            role="group"
            aria-roledescription="slide"
            aria-label={`${i + 1} of ${total}`}
            hidden={i !== index}
          >
            <img src={photo.src} alt={photo.alt} />
          </div>
        ))}
      </div>
      <div className="carousel__controls">
        <button type="button" onClick={prev} aria-label="Previous photo">
          ←
        </button>
        <span className="carousel__count" aria-hidden="true">
          {index + 1} / {total}
        </span>
        <button type="button" onClick={next} aria-label="Next photo">
          →
        </button>
      </div>
    </section>
  )
}
