import { useId, useState } from 'react'

// Price with a small "i" button; the note is shown on hover/focus and
// dismissed with Escape. The tooltip is always in the DOM so the trigger
// can reference it with aria-describedby.
export default function PriceInfo({ price, currencySymbol }) {
  const [open, setOpen] = useState(false)
  const tipId = useId()
  const formatted = `${currencySymbol}${price.toFixed(2)}`

  return (
    <span
      className="price"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <span className="price__amount">{formatted}</span>
      <button
        type="button"
        className="price__info"
        aria-label="Price information"
        aria-describedby={tipId}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        onKeyDown={(e) => {
          if (e.key === 'Escape') setOpen(false)
        }}
      >
        i
      </button>
      <span
        id={tipId}
        role="tooltip"
        className="price__tip"
        hidden={!open}
      >
        Price includes all applicable taxes.
      </span>
    </span>
  )
}
