        </span>
        <button
          type="button"
          aria-expanded={open}
          aria-controls={panelId}
          onClick={() => setOpen((o) => !o)}
        >
          Change color
        </button>
      </div>
      <div id={panelId} hidden={!open}>
        {open ? (
          <div role="radiogroup" aria-labelledby={groupLabelId} className="color-picker__options">
            {colors.map((c) => (
              <label key={c.id} className="swatch" style={{ '--swatch': c.hex }}>
                <input
                  type="radio"
                  name="color"
                  value={c.id}
                  checked={value === c.id}
                  onChange={() => onChange(c.id)}
                  aria-label={c.label}
                />
              </label>
            ))}
          </div>
        ) : null}
      </div>
    </div>
  )
}
