import { useId, useRef, useState } from 'react'

export function sizeText(s) {
  return `${s.label} (EU ${s.eu})`
}

// APG select-only combobox. The list only exists while open.
export default function SizePicker({ sizes, value, onChange, invalid, describedBy }) {
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const labelId = useId()
  const listId = useId()
  const comboRef = useRef(null)
  const chosen = value == null ? null : sizes[value]

  const enabledIndex = (from, dir) => {
    let i = from
    while (i >= 0 && i < sizes.length) {
      if (!sizes[i].soldOut) return i
      i += dir
    }
    return from
  }

  const openList = () => {
    setActive(value ?? enabledIndex(0, 1))
    setOpen(true)
  }
  const close = () => setOpen(false)

  const pick = (i) => {
    if (sizes[i].soldOut) return
    onChange(i)
    close()
  }

  const onKeyDown = (e) => {
    if (!open) {
      if (['Enter', ' ', 'ArrowDown', 'ArrowUp'].includes(e.key)) {
        e.preventDefault()
        openList()
      }
      return
    }
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setActive((a) => enabledIndex(Math.min(a + 1, sizes.length - 1), 1))
        break
      case 'ArrowUp':
        e.preventDefault()
        setActive((a) => enabledIndex(Math.max(a - 1, 0), -1))
        break
      case 'Home':
        e.preventDefault()
        setActive(enabledIndex(0, 1))
        break
      case 'End':
        e.preventDefault()
        setActive(enabledIndex(sizes.length - 1, -1))
        break
      case 'Enter':
      case ' ':
        e.preventDefault()
        pick(active)
        break
      case 'Escape':
        e.preventDefault()
        close()
        break
      case 'Tab':
        close()
        break
      default:
    }
  }

  return (
    <div className="size-picker">
      <span id={labelId} className="size-picker__label">
        Size
      </span>
      <div
        ref={comboRef}
        role="combobox"
        tabIndex={0}
        className="size-picker__combo"
        aria-labelledby={labelId}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listId : undefined}
        aria-activedescendant={open ? `${listId}-${active}` : undefined}
        aria-invalid={invalid ? 'true' : undefined}
        aria-describedby={describedBy}
        onClick={() => (open ? close() : openList())}
        onKeyDown={onKeyDown}
        onBlur={close}
      >
        {chosen ? sizeText(chosen) : 'Choose size (US 7–12)'}
      </div>
      {open ? (
        <ul
          id={listId}
          role="listbox"
          aria-labelledby={labelId}
          className="size-picker__list"
          onMouseDown={(e) => e.preventDefault()}
        >
          {sizes.map((s, i) => (
            <li
              key={s.label}
              id={`${listId}-${i}`}
              role="option"
              aria-selected={value === i}
              aria-disabled={s.soldOut ? 'true' : undefined}
              className={[
                i === active ? 'is-active' : '',
                s.soldOut ? 'is-sold-out' : '',
              ].join(' ')}
              onClick={() => pick(i)}
            >
              {sizeText(s)}
              {s.soldOut ? <span className="sold-out"> — sold out</span> : null}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}
