import { useEffect, useId, useRef, useState } from 'react'

// Trigger button, rendered next to the size picker.
export function SizeGuideButton({ buttonRef, onOpen }) {
  return (
    <button type="button" className="size-guide-button" ref={buttonRef} onClick={onOpen}>
      Size guide
    </button>
  )
}

// Modal size chart. The parent makes the rest of the page inert while open.
export function SizeGuideDialog({ chart, onClose }) {
  const titleId = useId()
  const dialogRef = useRef(null)
  const [footCm, setFootCm] = useState('')
  const [system, setSystem] = useState('US')
  const [result, setResult] = useState('')

  useEffect(() => {
    dialogRef.current?.querySelector('input')?.focus()
  }, [])

  const focusables = () =>
    Array.from(
      dialogRef.current.querySelectorAll(
        'button, input, [href], select, textarea, [tabindex]:not([tabindex="-1"])',
      ),
    ).filter((el) => !el.disabled)

  const onKeyDown = (e) => {
    if (e.key === 'Escape') {
      e.preventDefault()
      onClose()
      return
    }
    if (e.key !== 'Tab') return
    const items = focusables()
    if (items.length === 0) return
    const first = items[0]
    const last = items[items.length - 1]
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault()
      last.focus()
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault()
      first.focus()
    }
  }

  const compute = () => {
    const cm = parseFloat(footCm)
    if (Number.isNaN(cm)) {
      setResult('Enter your foot length in centimetres.')
      return
    }
    const entry = chart.reduce((best, row) =>
      Math.abs(row.footCm - cm) < Math.abs(best.footCm - cm) ? row : best,
    )
    setResult(`Your size: ${system} ${system === 'US' ? entry.us : entry.eu}`)
  }

  return (
    <div className="modal-backdrop">
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="modal"
        onKeyDown={onKeyDown}
      >
        <div className="modal__header">
          <h2 id={titleId}>Size guide</h2>
          <button type="button" aria-label="Close size guide" onClick={onClose}>
            ×
          </button>
        </div>

        <table className="size-table">
          <thead>
            <tr>
              <th scope="col">Foot length (cm)</th>
              <th scope="col">US</th>
              <th scope="col">EU</th>
            </tr>
          </thead>
          <tbody>
            {chart.map((row) => (
              <tr key={row.footCm}>
                <td>{row.footCm.toFixed(1)}</td>
                <td>{row.us}</td>
                <td>{row.eu}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="modal__finder">
          <label>
            Foot length (cm)
            <input
              type="number"
              inputMode="decimal"
              min="20"
              max="35"
              step="0.5"
              value={footCm}
              onChange={(e) => setFootCm(e.target.value)}
            />
          </label>
          <fieldset className="modal__system">
            <legend>Size system</legend>
            {['US', 'EU'].map((s) => (
              <label key={s}>
                <input
                  type="radio"
                  name="size-system"
                  value={s}
                  checked={system === s}
                  onChange={() => setSystem(s)}
                />
                {s}
              </label>
            ))}
          </fieldset>
          <button type="button" onClick={compute}>
            My size
          </button>
          <p role="status">{result}</p>
        </div>
      </div>
    </div>
  )
}
