import { useId, useRef, useState } from 'react'

// APG tabs with automatic activation: arrow, Home and End keys move and select.
export default function InfoTabs({ tabs }) {
  const baseId = useId()
  const [selected, setSelected] = useState(0)
  const refs = useRef([])

  const select = (i) => {
    setSelected(i)
    refs.current[i]?.focus()
  }

  const onKeyDown = (e, i) => {
    const last = tabs.length - 1
    let next = null
    if (e.key === 'ArrowRight') next = i === last ? 0 : i + 1
    else if (e.key === 'ArrowLeft') next = i === 0 ? last : i - 1
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = last
    if (next !== null) {
      e.preventDefault()
      select(next)
    }
  }

  const tab = tabs[selected]
  const tabId = (i) => `${baseId}-tab-${i}`
  const panelId = `${baseId}-panel`

  return (
    <section className="info-tabs" aria-label="Product information">
      <div role="tablist" aria-label="Product information">
        {tabs.map((t, i) => (
          <button
            key={t.label}
            id={tabId(i)}
            ref={(el) => (refs.current[i] = el)}
            type="button"
            role="tab"
            aria-selected={i === selected}
            aria-controls={panelId}
            tabIndex={i === selected ? 0 : -1}
            onClick={() => setSelected(i)}
            onKeyDown={(e) => onKeyDown(e, i)}
          >
            {t.label}
          </button>
        ))}
      </div>
      <div
        id={panelId}
        role="tabpanel"
        aria-labelledby={tabId(selected)}
        tabIndex={0}
        className="info-tabs__panel"
      >
        {tab.content}
      </div>
    </section>
  )
}
